using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Quotations.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.Quotations.Queries.GetQuotations;public sealed class GetQuotationsQueryHandler(IQuotationRepository repository):IRequestHandler<GetQuotationsQuery,Result<IReadOnlyList<QuotationDto>>>{public async Task<Result<IReadOnlyList<QuotationDto>>>Handle(GetQuotationsQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<QuotationDto>>((await repository.GetAllAsync(cancellationToken)).Select(QuotationDto.FromEntity).ToList());}

